exercise.solution:
function validateTask(dto: {
    title?: string;
    dueDate?: string;
    priority?: string;
}): { field: string; message: string }[] {
    const errors: { field: string; message: string }[] = [];

    if (dto.title === undefined || dto.title.trim() === "") {
        errors.push({ field: "title", message: "must not be blank" });
    } else if (dto.title.length > 100) {
        errors.push({ field: "title", message: "size must be at most 100" });
    }

    if (dto.dueDate !== undefined) {
        const matchesFormat = /^\d{4}-\d{2}-\d{2}$/.test(dto.dueDate);
        let validDate = false;

        if (matchesFormat) {
            const [year, month, day] = dto.dueDate.split("-").map(Number);
            const date = new Date(Date.UTC(year, month - 1, day));
            validDate = date.getUTCFullYear() === year
                && date.getUTCMonth() === month - 1
                && date.getUTCDate() === day;
        }

        if (!validDate) {
            errors.push({ field: "dueDate", message: "must be a valid date" });
        }
    }

    if (dto.priority !== undefined && !["low", "normal", "high"].includes(dto.priority)) {
        errors.push({
            field: "priority",
            message: "must be one of low, normal, high"
        });
    }

    return errors;
}

function toProblemDetail(errors: { field: string; message: string }[]) {
    return {
        type: "about:blank",
        title: "Bad Request",
        status: 400,
        detail: "Validation failed",
        errors
    };
}

