const problem = toProblemDetail(errors);
return errors.length === 0 && problem.type === "about:blank" && problem.title === "Bad Request" && problem.status === 400 && problem.detail === "Validation failed" && Array.isArray(problem.errors) && problem.errors.length === 0;
